{
  "work_definition_version": 0,
  "task_family": "reconciliation",
  "model_id": "amount-recon-amount-compare-within-tolerance",
  "provenance": {
    "producer": "goose-skill-session-e2",
    "skill": "define-lab-process",
    "produced_at": "2026-08-20"
  },
  "purpose": "reconcile supplier statement with internal ledger by matching on InvoiceNumber and comparing Amount within GBP 0.01 tolerance",
  "sources": {
    "supplier-statement": {
      "role_label": "Supplier Statement",
      "fixture": "supplier-statement.txt",
      "observed_fields": ["Date", "Supplier Name", "InvoiceNumber", "Amount", "Currency", "Status"],
      "basis": "observed"
    },
    "ledger-book": {
      "role_label": "Internal Ledger Book",
      "fixture": "ledger-book.txt",
      "observed_fields": ["Date", "ReferenceNumber", "SupplierName", "InvoiceNumber", "Amount", "Status", "Notes"],
      "basis": "observed"
    }
  },
  "body": {
    "left": "supplier-statement",
    "right": "ledger-book",
    "match_on": {
      "left_field": "InvoiceNumber",
      "right_field": "InvoiceNumber",
      "basis": "human_confirmed",
      "confirmation": "Q_match_key"
    },
    "compare": [
      {
        "field": "Amount",
        "comparison": "within",
        "tolerance": "0.01",
        "basis": "human_confirmed",
        "confirmation": "Q_compare_field"
      }
    ],
    "classify": {
      "both_same": "matched",
      "both_different": "amount_mismatch",
      "only_left": "missing_from_ledger",
      "only_right": "unmatched_in_statement"
    },
    "output_order": "left_then_right",
    "on_duplicate_key": "refuse_run",
    "on_non_numeric": "refuse_key"
  },
  "output": {
    "reports_fields": ["InvoiceNumber", "Amount"],
    "context_fields": ["Date", "Supplier Name", "Status"]
  },
  "human_confirmations": [
    {
      "id": "Q_match_key",
      "question": "Which field identifies the same record in both files?",
      "answer": "InvoiceNumber",
      "basis": "human_confirmed"
    },
    {
      "id": "Q_compare_field",
      "question": "Which field should be compared between matched records, and with what comparison and tolerance?",
      "answer": "Amount numerically within 0.01",
      "basis": "human_confirmed"
    }
  ],
  "open_questions": [
    {
      "id": "Q_status_difference",
      "question": "How should the Status field difference (PAID vs CLEARED/PENDING) be handled in classification?",
      "load_bearing": false,
      "status": "unresolved"
    }
  ],
  "requested_destination": "review_only",
  "requested_delivery": {
    "format": "json_discrepancy_report"
  },
  "requested_authority": null
}
